"""Migration of Meridian CRM 4.2 ACCT_MASTER validation rules."""

from decimal import Decimal
from typing import Any


def _value(record: dict, field: str) -> Any:
    """Return a field value using legacy missing-field semantics."""
    return record.get(field, "")


def _length(value: Any) -> int:
    """Implement VRL LEN with missing/null values treated as empty."""
    if value is None or value == "":
        return 0
    return len(str(value))


def _nvl(value: Any, default: Any) -> Any:
    """Implement VRL NVL."""
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Implement legacy numeric-context coercion for empty values."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    del today  # Present for the fixed interface; unused by these rules.

    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        # ACC-001
        if _length(_value(record, "ACCT_NM")) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

        # ACC-002
        acct_typ = _value(record, "ACCT_TYP")
        if not (
            acct_typ == "C"
            or acct_typ == "P"
            or acct_typ == "R"
            or acct_typ == "X"
        ):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

        # ACC-003
        if _number(_nvl(_value(record, "ANN_REV"), 0)) < 0:
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    # ACC-004 is UPDATE-only.
    if event == "UPDATE":
        old_record = old or {}
        if (
            _value(old_record, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        ):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        # ACC-005
        if _length(_value(record, "REGION_CD")) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected legacy validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
